function officeFilters(){return `<section class="office-filter-panel" aria-labelledby="office-filters-title"><div class="panel-title"><h3 id="office-filters-title">${t('Office HVAC filters','办公室空调过滤')}</h3></div><p class="fineprint">${t('Haze-planning default: MERV 14 for both outdoor and recirculated air, following NEA guidance. Confirm the installed grades and airflows with your facilities team.','雾霾规划默认采用 MERV 14，参考 NEA 对新风和回风的建议。请向设施管理人员确认实际滤网等级与风量。')}</p>${['supply','recirculation'].map(stream=>{const selection=p[stream+'Filter']??'custom',eff=p[stream+'Efficiency'];return `<div class="hvac-filter-control"><label class="field"><span>${stream==='supply'?t('Outdoor-air filter','新风过滤器'):t('Recirculated-air filter','回风过滤器')}</span><select id="${stream}-filter" data-hvac-filter="${stream}">${selectOptions(FILTER_OPTIONS.map(option=>[option.id,option.id==='none'?t('No filter','无过滤器'):option.id==='custom'?t('Enter measured efficiency','输入实测效率'):'MERV '+option.grade]),selection)}</select></label><div class="filter-efficiency"><span>${t('Efficiency used in the model','模型采用的过滤效率')}</span><strong data-filter-efficiency="${stream}">${Number.isFinite(eff)?number(eff*100,Number.isInteger(eff*100)?0:1)+'%':'—'}</strong></div>${selection==='custom'?field(stream+'Efficiency','0–1','any',t('Use a measured PM₂.₅ efficiency, including filter bypass','填写含旁路影响的实测 PM₂.₅ 效率')):''}${/^merv(?:[1-9]|10)$/.test(selection)?`<p class="fineprint filter-grade-note">${t('This grade has no specified 0.3–1 µm minimum. The model credits 0%; enter measured efficiency if available.','该等级未规定 0.3–1 µm 最低效率，模型计入 0%；如有实测值，可选择输入实测效率。')}</p>`:''}</div>`;}).join('')}<p class="fineprint filter-model-note">${t('MERV lookup uses the 0.3–1 µm minimum as a fine-particle proxy, not a certified whole-PM₂.₅ efficiency. Actual capture depends on particle sizes and installation.','MERV 查表采用 0.3–1 µm 最低效率作为细颗粒近似，不是经认证的 PM₂.₅ 总体效率。实际效果取决于粒径及安装情况。')}</p><p class="fineprint">${t('If one AHU filters both air streams, choose its grade for both. Change airflows under “Refine the assumptions”; recirculated flow excludes outdoor air.','若同一 AHU 过滤两路气流，两处选择相同等级。风量可在“调整详细参数”中修改；回风风量不含新风。')}</p><div class="office-filter-sources">${refs(['nea-vent','epa-merv'],{}, {'nea-vent':t('Section 2.3(a)','第 2.3(a) 节')})}</div></section>`;}
